// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // Fuzz the from address and a boolean that decides whether we pass an empty _tos array.
    // General rule: reference contract always reverts when _tos is empty; mutant does not.
    function testFuzz_property(address from, bool empty) public {
        // keep domain wide: avoid zero-address for from only if needed by environment
        // but allow any address (including zero) since reference revert condition depends only on _tos.length

        // Prepare _tos according to fuzzed 'empty' flag
        address[] memory tos;
        if (empty) {
            tos = new address[](0);
        } else {
            tos = new address[](1);
            tos[0] = address(0xdead);
        }

        bool ok;
        // call transfer and observe whether it reverts (reference must revert when empty)
        try c.transfer(from, address(0xBEEF), tos, uint(1)) {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: when we pass an empty _tos array, reference contract should always revert (ok == false)
        // This assertion is true for the correct contract and will fail for the mutant for the case empty == true
        if (empty) {
            assertTrue(!ok);
        } else {
            // For non-empty arrays both should succeed; assert that it did not revert so the test remains universal
            assertTrue(ok);
        }
    }
}
